import React, { useState, useEffect } from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate, useLocation } from 'react-router-dom';

import Header from './components/Clients/Widgets/Header/Header';
import Footer from './components/Clients/Widgets/Footer/Footer';

import Login from './components/Clients/Auth/Login';
import Register from './components/Clients/Auth/Register';

import Home from './components/Clients/Home/Home';
import Dashboard from './components/Clients/Widgets/DashboardLayout';
import ProtectedRoute from './components/Clients/Auth/ProtectedRoute';

// Pages du Header
import Contact from './components/Clients/Contact/Contact';
import Portfolio from './components/Clients/Portfolio/Portfolio';
import Services from './components/Clients/Services/Services';

// ----------------------------
// Composant Principal App
// ----------------------------

function App() {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [userRole, setUserRole] = useState(null);
  const [isLoading, setIsLoading] = useState(true);
  const location = useLocation();

  // Vérifier la session user
  useEffect(() => {
    const userEmail = localStorage.getItem('userEmail');
    const token = localStorage.getItem('authToken');
    const userData = localStorage.getItem('userData');

    if (userEmail || token) {
      setIsAuthenticated(true);
      if (userData) {
        const user = JSON.parse(userData);
        setUserRole(user.role || 'user');
      }
    }

    setIsLoading(false);
  }, []);

  // Connexion
  const handleLogin = (userData) => {
    localStorage.setItem('userEmail', userData.email);
    localStorage.setItem('userData', JSON.stringify(userData));
    setUserRole(userData.role || 'user');
    setIsAuthenticated(true);
  };

  // Déconnexion
  const handleLogout = () => {
    localStorage.removeItem('authToken');
    localStorage.removeItem('userEmail');
    localStorage.removeItem('userData');
    localStorage.removeItem('rememberMe');
    setIsAuthenticated(false);
    setUserRole(null);
  };

  // Loader
  if (isLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-white dark:bg-neutral-950">
        <div className="text-center">
          <div className="h-12 w-12 border-4 border-primary-500 border-t-transparent rounded-full animate-spin mx-auto"></div>
          <p className="mt-4 text-neutral-600 dark:text-neutral-400">Chargement...</p>
        </div>
      </div>
    );
  }

  // Cacher Header / Footer
  const hideUi = location.pathname.startsWith('/dashboard');

  return (
    <>
      {!hideUi && <Header isAuthenticated={isAuthenticated} onLogout={handleLogout} />}

      <div className="min-h-screen bg-white dark:bg-neutral-950 text-neutral-900 dark:text-white">
        <Routes>

          {/* HOME */}
          <Route path="/" element={<Home />} />

          {/* AUTH */}
          <Route
            path="/login"
            element={
              isAuthenticated ? <Navigate to="/dashboard" replace /> : <Login onLogin={handleLogin} />
            }
          />

          <Route
            path="/register"
            element={
              isAuthenticated ? <Navigate to="/dashboard" replace /> : <Register />
            }
          />

          {/* DASHBOARD PROTÉGÉ */}
          <Route
            path="/dashboard/*"
            element={
              <ProtectedRoute isAuthenticated={isAuthenticated}>
                <Dashboard onLogout={handleLogout} />
              </ProtectedRoute>
            }
          />

          {/* 🚀 PAGES DU HEADER */}
          <Route path="/contact" element={<Contact />} />
          <Route path="/portfolio" element={<Portfolio />} />
          <Route path="/services" element={<Services />} />

          {/* NOT FOUND */}
          <Route path="*" element={<Navigate to="/" replace />} />
        </Routes>
      </div>

      {!hideUi && <Footer />}
    </>
  );
}

// Wrapper Router
function AppWrapper() {
  return (
    <Router>
      <App />
    </Router>
  );
}

export default AppWrapper;
